//! Same authored variant workload for an explicitly selected source pair.
const std = @import("std");
const boundary = @import("boundary");
const world = @import("world");
const data = if (@hasDecl(boundary, "data")) boundary.data else boundary.data_v2;
const source = boundary.source;
const current = @hasDecl(world, "Session");
const protocol = if (current) data.invocation else data.protocol;
const runtime = if (current) world else world.process_v2;

const Fixture = enum { product, variant, sequence };
fn add(b: *source.Builder, integer: u64, left: u64, right: u64) !u64 {
    return b.value(.{ .schema = integer, .expression = .{ .primitive = .{ .opcode = .integer_add, .operands = &.{ left, right }, .failures = &.{.{ .kind = .arithmetic_overflow, .value = try b.failureLiteral(try b.constant(void, {})) }} } } });
}
fn module(b: *source.Builder, fixture: Fixture) !source.Module {
    const integer = try b.scalar(u64);
    const unit = try b.scalar(void);
    if (fixture == .sequence) {
        const sequence = try b.schema(.{ .seq = integer });
        const pair = try b.schema(.{ .product = &.{ integer, sequence } });
        const optional = try b.schema(.{ .sum = &.{ unit, pair } });
        const entry = try b.declare(&.{ sequence, integer }, integer, &.{}, &.{});
        const sum = try b.reference(b.parameter(entry, 1));
        const empty = try b.variable(unit);
        const present = try b.variable(pair);
        const head = try b.variable(integer);
        const tail = try b.variable(sequence);
        const recurse = try b.term(.{ .call = .{ .function = entry, .arguments = &.{ try b.reference(tail), try add(b, integer, sum, try b.reference(head)) } } });
        try b.define(entry, try b.term(.{ .match_sum = .{
            .value = try b.primitive(optional, .sequence_pop, &.{try b.reference(b.parameter(entry, 0))}, 0),
            .cases = &.{ .{ .variable = empty, .body = try b.pure(sum) }, .{ .variable = present, .body = try b.term(.{ .unpack_product = .{ .value = try b.reference(present), .variables = &.{ head, tail }, .body = recurse } }) } },
        } }));
        return b.module(entry, unit);
    }
    const bytes = try b.schema(.bytes);
    const aggregate = try b.schema(if (fixture == .product) .{ .product = &.{ integer, bytes } } else .{ .sum = &.{ bytes, unit } });
    const entry = try b.declare(&.{ aggregate, integer, integer }, integer, &.{}, &.{});
    const value = try b.reference(b.parameter(entry, 0));
    const count = try b.reference(b.parameter(entry, 1));
    const sum = try b.reference(b.parameter(entry, 2));
    const selected = try b.primitive(integer, if (fixture == .product) .field else .variant_tag, &.{value}, 0);
    const decrement = try b.value(.{ .schema = integer, .expression = .{ .primitive = .{ .opcode = .integer_sub, .operands = &.{ count, try b.constant(u64, 1) }, .failures = &.{.{ .kind = .arithmetic_overflow, .value = try b.failureLiteral(try b.constant(void, {})) }} } } });
    try b.define(entry, try b.term(.{ .conditional = .{
        .condition = try b.primitive(try b.scalar(bool), .equal, &.{ count, try b.constant(u64, 0) }, 0),
        .when_true = try b.pure(sum),
        .when_false = try b.term(.{ .call = .{ .function = entry, .arguments = &.{ value, decrement, try add(b, integer, sum, selected) } } }),
    } }));
    return b.module(entry, unit);
}
fn command(a: std.mem.Allocator, compact: bool, fixture: Fixture, size: usize) ![]u8 {
    var b = source.Builder.init(a);
    defer b.deinit();
    var compiled = try source.lower(a, try module(&b, fixture));
    defer compiled.deinit();
    const length = if (current) try data.program_image.encodedLength(compiled.program) else if (compact) try data.compact_image.encodedLength(a, compiled.program) else try data.image.encodedLength(compiled.program);
    const image = try a.alloc(u8, length);
    defer a.free(image);
    if (current) {
        _ = try compiled.encode(a, image);
    } else if (compact) {
        _ = try data.compact_image.encode(a, compiled.program, image);
    } else {
        _ = try compiled.encode(a, image);
    }
    const args = try a.alloc(u8, (if (fixture == .sequence) size * 8 else size) + 32);
    defer a.free(args);
    var writer: data.wire.Writer = .{ .output = args };
    if (fixture == .sequence) {
        try writer.natural(size);
        for (0..size) |i| try writer.fixed(u64, i + 1);
    } else {
        if (fixture == .product) try writer.fixed(u64, 42) else try writer.natural(0);
        try writer.natural(size);
        for (0..size) |_| try writer.byte(0xa7);
        try writer.fixed(u64, 256);
    }
    try writer.fixed(u64, 0);
    const input: protocol.Input = if (current) .{ .image = image, .instance = .{ .initial_args = args[0..writer.position] } } else .{ .mode = .run, .image = image, .instance = .{ .initial_args = args[0..writer.position] }, .control = .{ .continue_value = null } };
    const encoded = try a.alloc(u8, try protocol.encodedLength(protocol.Input, input));
    errdefer a.free(encoded);
    _ = try protocol.encode(protocol.Input, a, input, encoded);
    return encoded;
}

fn invoke(a: std.mem.Allocator, input: []const u8, output: []u8) ![]const u8 {
    if (current) return world.invocation.invokeInto(a, input, output);
    const decoded = try protocol.decode(protocol.Input, a, input);
    var result = try runtime.invoke(a, decoded);
    defer result.deinit();
    return protocol.encode(protocol.Outcome, a, result.record, output);
}

fn verify(a: std.mem.Allocator, bytes: []const u8, expected: u64) !void {
    if (current) {
        var decoded = try protocol.decode(protocol.Outcome, a, bytes);
        defer decoded.deinit();
        if (decoded.value != .completed or decoded.value.completed.len != 8 or
            std.mem.readInt(u64, decoded.value.completed[0..8], .little) != expected)
            return error.UnexpectedResult;
    } else {
        var scratch = std.heap.ArenaAllocator.init(a);
        defer scratch.deinit();
        const decoded = try protocol.decode(protocol.Outcome, scratch.allocator(), bytes);
        if (decoded != .completed or decoded.completed.len != 8 or std.mem.readInt(u64, decoded.completed[0..8], .little) != expected)
            return error.UnexpectedResult;
    }
}

pub fn main(init: std.process.Init) !void {
    var args = std.process.Args.Iterator.init(init.minimal.args);
    _ = args.next();
    const format = args.next() orelse return error.ExpectedFormat;
    const fixture = std.meta.stringToEnum(Fixture, args.next() orelse return error.ExpectedFixture) orelse return error.InvalidFixture;
    const size = try std.fmt.parseInt(usize, args.next() orelse return error.ExpectedSize, 10);
    if (size > (if (fixture == .sequence) @as(usize, 4096) else 1 << 20) or args.next() != null) return error.InvalidFixture;
    const expected: u64 = switch (fixture) {
        .product => 42 * 256,
        .variant => 0,
        .sequence => size * (size + 1) / 2,
    };
    if (!std.mem.eql(u8, format, if (current) "bpi3" else "bpi2") and
        (current or !std.mem.eql(u8, format, "bpc1"))) return error.InvalidFormat;
    const input = try command(init.gpa, std.mem.eql(u8, format, "bpc1"), fixture, size);
    defer init.gpa.free(input);
    const storage = try init.gpa.alloc(u8, 128 << 20);
    defer init.gpa.free(storage);
    var samples: [9]u64 = undefined;
    var peak: usize = 0;
    var allocations: usize = 0;
    var allocated_bytes: usize = 0;
    for (0..12) |iteration| {
        var output: [256]u8 = undefined;
        const started = std.Io.Clock.awake.now(init.io);
        var arena = runtime.Workspace.init(storage);
        const encoded = try invoke(arena.allocator(), input, &output);
        const elapsed: u64 = @intCast(started.durationTo(std.Io.Clock.awake.now(init.io)).nanoseconds);
        try verify(init.gpa, encoded, expected);
        if (iteration >= 3) samples[iteration - 3] = elapsed;
    }
    // Allocation counters are a separate replay, outside acceptance timings.
    var arena = runtime.Workspace.init(storage);
    var tracked = std.testing.FailingAllocator.init(arena.allocator(), .{});
    var output: [256]u8 = undefined;
    try verify(init.gpa, try invoke(tracked.allocator(), input, &output), expected);
    peak = arena.peak_payload;
    allocations = tracked.allocations;
    allocated_bytes = tracked.allocated_bytes;
    var buffer: [4096]u8 = undefined;
    var stdout = std.Io.File.stdout().writer(init.io, &buffer);
    try std.json.Stringify.value(.{ .format = format, .fixture = @tagName(fixture), .size = size, .input_bytes = input.len, .input_sha256 = std.fmt.bytesToHex(data.wire.digest(input), .lower), .samples_ns = samples, .working_capacity = storage.len, .peak_working_payload_bytes = peak, .allocation_calls = allocations, .allocated_bytes = allocated_bytes, .expected = expected }, .{}, &stdout.interface);
    try stdout.interface.writeByte('\n');
    try stdout.interface.flush();
}

drivers.valueBuildSource:
//! Explicit source-pair benchmark; no historical dependency enters normal builds.
const std = @import("std");
pub fn build(b: *std.Build) void {
    const boundary_source = b.option([]const u8, "boundary-source", "Frozen Boundary source") orelse
        @panic("provide -Dboundary-source");
    const world_source = b.option([]const u8, "world-source", "Frozen World source") orelse
        @panic("provide -Dworld-source");
    const legacy_names = b.option(bool, "legacy-names", "Use module names of the frozen older checkout") orelse false;
    const data_name = if (legacy_names) "boundary_data_v2" else "boundary_data";
    const data = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ boundary_source, "src/v2/data/root.zig" }) }, .target = b.graph.host, .optimize = .ReleaseSafe });
    const boundary = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ boundary_source, "src/v2/root.zig" }) }, .target = b.graph.host, .optimize = .ReleaseSafe, .imports = &.{.{ .name = data_name, .module = data }} });
    const world = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ world_source, "src/root.zig" }) }, .target = b.graph.host, .optimize = .ReleaseSafe, .imports = &.{.{ .name = data_name, .module = data }} });
    const root = b.createModule(.{ .root_source_file = b.path("data_bench.zig"), .target = b.graph.host, .optimize = .ReleaseSafe, .imports = &.{ .{ .name = "boundary", .module = boundary }, .{ .name = "world", .module = world } } });
    b.installArtifact(b.addExecutable(.{ .name = "data-bench", .root_module = root }));
}

